package com.example.billing.domain;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="PaymentAttempts",uniqueConstraints=@UniqueConstraint(name="IX_PaymentAttempts_PaymentId_AttemptNumber",columnNames={"PaymentId","AttemptNumber"})) public class PaymentAttempt { @Id @Column(name="Id") public UUID id; @Column(name="PaymentId",nullable=false,insertable=false,updatable=false) public UUID paymentId; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="PaymentId",nullable=false) public Payment payment; @Column(name="AttemptNumber",nullable=false) public int attemptNumber; @Column(name="Status",length=50,nullable=false) public String status; @Column(name="FailureReason",length=500) public String failureReason; @Column(name="CreatedAt",nullable=false) public OffsetDateTime createdAt; }
